import assert from 'node:assert/strict';import {chromium} from 'playwright-core'
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--enable-webgl','--ignore-gpu-blocklist','--use-angle=metal']});try{const page=await browser.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://127.0.0.1:5277/qa/exo-avatar-hybrid-precision-20261102.html',{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>window.__exoHybridPreciseTest!==null,null,{timeout:50000});const result=await page.evaluate(()=>window.__exoHybridPreciseTest);console.log('EXO_HYBRID_PRECISION_QA',JSON.stringify({result,errors},null,2));assert.ok(!result.error,result.error);assert.equal(result.aligned,true);assert.ok(result.skinAlignmentMm<2);assert.equal(result.rigBones,163);assert.ok(result.fiberVertices>=28000);assert.ok(result.hairMovedMm>10,'Head bone must deform hair');assert.ok(result.styledHairMeshes>=2);assert.deepEqual(errors,[])}finally{await browser.close()}
